/**
 * The four thinking-level backdrops, extracted verbatim from dsh-smooth-skin
 * (its THINK_ART table). They are WebP data URIs so the panel needs no asset
 * request and no packaging step; the build inlines this module into the bundle.
 *
 * Generated file: do not hand-edit. Re-extract from dsh-smooth-skin when the
 * artwork changes.
 */
const THINK_ART = Object.freeze({
  off: 'data:image/webp;base64,',
  low: 'data:image/webp;base64,',
  high: 'data:image/webp;base64,',
  max: 'data:image/webp;base64,',
});
